/* while statement */
$i: 6;
@while $i > 0 {
  .item-#{$i} { width: 2em * $i; }
  $i: $i - 2;
}

/* function with controlstatements */
@function foo($total, $a) {
  @for $i from 0 to $total {
    @if (unit($a) == "%") and ($i == ($total - 1)) {
      $z: 100%;
      @return '1';
    }
  }
  @return $grid;
}

